let started=false;
export function scheduleCafePreload(){if(started||navigator.connection?.saveData)return;started=true;const begin=()=>setTimeout(()=>{let next=0;async function worker(){while(next<assets.length){const url=assets[next++];try{if(/\.(png|webp)$/.test(url))await new T.ImageLoader().loadAsync(url);else if(url.includes('/coast/'))await new T.FileLoader().setResponseType('arraybuffer').loadAsync(url);else await cafeAssetBytes(url)}catch{}}}void Promise.all([worker(),worker()])},5000);if(document.readyState==='complete')begin();else window.addEventListener('load',begin,{once:true})}
